CREATE TABLE `velix_production_stages` (`id` text PRIMARY KEY NOT NULL, `run_id` text NOT NULL REFERENCES `velix_production_runs`(`id`) ON DELETE CASCADE, `kind` text NOT NULL, `status` text NOT NULL, `input_hash` text NOT NULL, `output_artifact_ids` text NOT NULL DEFAULT '[]', `progress` real NOT NULL DEFAULT 0, `retry_count` integer NOT NULL DEFAULT 0, `cost_estimate_usd` real NOT NULL DEFAULT 0, `actual_cost_usd` real NOT NULL DEFAULT 0, `checkpoint` text NOT NULL DEFAULT '{}', `error` text, `task_id` text, `created_at` text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), `updated_at` text NOT NULL DEFAULT (datetime('now')))
